function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function badge(s){let c=/livr|payée|actif|valide|résolu/i.test(s)?'green':/retard|haute/i.test(s)?'red':/attente|proche|renouveler/i.test(s)?'orange':/ouvert|transit|cours|partielle/i.test(s)?'':'purple';return `<span class="badge ${c}">${esc(s)}</span>`}
function metric(label,value,note='',tone=''){return `<div class="metric"><label>${label}</label><strong>${value}</strong>${note?`<small class="${tone}">${note}</small>`:''}</div>`}
function title(h1,sub,action=''){return `<div class="heading"><div><h1>${h1}</h1><p class="sub">${sub}</p></div>${action?`<button class="primary" data-action="${action}">＋　${actionLabel(action)}</button>`:''}</div>`}
function actionLabel(a){return ({'Nouvelle expédition':'Nouvelle expédition','Nouvel appel d’offres':'Nouvel appel d’offres','Ajouter un chargeur':'Ajouter un chargeur','Ajouter un transporteur':'Ajouter un transporteur','Importer un document':'Importer un document','Nouveau client':'Nouveau client','Créer une facture':'Créer une facture','Déclarer un litige':'Déclarer un litige','Créer une demande':'Créer une demande','Proposer mon offre':'Proposer mon offre'})[a]||a}
function table(headers,rows,kind='generic',activeSelected=selected){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr data-row="${kind}" data-index="${i}" class="${(kind==='docs'?docs.findIndex(d=>d[0]===row[0])===selectedDocument:kind==='billing'?i===selectedBill:kind==='disputes'?i===selectedDispute:kind==='risk'?i===selectedRisk:i===activeSelected)?'selected':''}">${row.map((v,j)=>`<td>${kind==='risk'&&j===3?riskBadge(v):(j===0&&(kind==='shipments'||kind==='offers'||kind==='invoices'||kind==='disputes'||kind==='docs'||kind==='billing'||kind==='risk'))?`<span class="link">${esc(v)}</span>`:(/^(Actif|Valide|À compléter|À renouveler|En retard|Livrée|En transit|Chargement|Ouvert|Côture proche|Partielle|À payer|Payée|En attente|En cours|Résolu|Haute|Normale|Reçu|Accepté|Envoyé|Émis)$/.test(v)?badge(v):esc(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
