function formFields(names){return `<div class="form-grid">${names.map(n=>`<div class="field"><label>${n}</label><input placeholder="${n==='Tarif HT (MAD)'?'4 800':n==='Délai estimé'?'24 heures':n==='Chargement'?'Tanger, zone franche':n==='Livraison'?'Casablanca, Sidi Bernoussi':n==='Marchandises'?'Palettes de pièces industrielles':n==='Commentaire'?'Assurance incluse · Chargement sur RDV':n==='Poids (t)'?'22':n==='Volume (m³)'?'68':'Sélectionner'}"></div>`).join('')}</div>`}
function render(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#workspaceTitle').textContent='Commissionnaire';document.querySelector('#workspaceSub').textContent='Atlas Logistics';document.querySelector('#context').textContent='Espace commissionnaire';let html=({dashboard,offers:offersPage,assignment:assignmentPage,tracking:trackingPage,documents:documentsPage,clients:clientsPage,billing:billingPageV2,disputes:disputesPage,settings:settingsPage,help:helpPage}[page]||dashboard)();document.querySelector('#app').innerHTML=cleanDemoCopy(html);makeMobileNav();if(page==='tracking')requestAnimationFrame(initShipmentMap);}
function initShipmentMap(){let el=document.querySelector('#trackingMap');if(!el)return;if(!window.L){el.innerHTML='<div class="map-fallback">La carte nécessite une connexion Internet. <a href="https://www.openstreetmap.org/" target="_blank" rel="noreferrer">Ouvrir OpenStreetMap</a></div>';return}if(window.logiflowMap){window.logiflowMap.remove();window.logiflowMap=null}let route=JSON.parse(el.dataset.route),position=JSON.parse(el.dataset.position),map=L.map(el,{scrollWheelZoom:false});window.logiflowMap=map;map.setView(route[Math.floor(route.length/2)],6);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors</a>'}).addTo(map);let line=L.polyline(route,{color:'#2860ed',weight:5,opacity:.86}).addTo(map);L.circleMarker(route[0],{radius:7,color:'#fff',weight:2,fillColor:'#16a37a',fillOpacity:1}).addTo(map).bindPopup(`<b>Départ</b><br>${esc(el.dataset.origin)}`);L.circleMarker(route[route.length-1],{radius:7,color:'#fff',weight:2,fillColor:'#e94357',fillOpacity:1}).addTo(map).bindPopup(`<b>Destination</b><br>${esc(el.dataset.destination)}`);L.circleMarker(position,{radius:8,color:'#fff',weight:3,fillColor:'#2860ed',fillOpacity:1}).addTo(map).bindPopup(`<b>${esc(el.dataset.reference)}</b><br>${esc(el.dataset.status)} · point de scénario`);map.fitBounds(line.getBounds(),{padding:[30,30]});L.control.scale({metric:true,imperial:false}).addTo(map);setTimeout(()=>map.invalidateSize(),100)}
function makeMobileNav(){let old=document.querySelector('.mobile-bottom');if(old)old.remove();let m=document.createElement('div');m.className='mobile-bottom';[['dashboard','Accueil'],['tracking','Suivi'],['documents','Documents'],['settings','Réglages']].forEach(([p,n])=>{let b=document.createElement('button');b.className=page===p?'active':'';b.innerHTML=`<span>${icon[p]}</span>${n}`;b.onclick=()=>go(p);m.append(b)});document.body.append(m)}
function go(p){page=p;query='';activeTab='';render();document.querySelector('#sidebar').classList.remove('open');window.scrollTo(0,0)}
function toast(s){let el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function cleanDemoCopy(value){return value.replace(/Données de démonstration/gi,'').replace(/Dossier de démonstration/gi,'Dossier LOGIFLOW').replace(/Document de démonstration · Les données présentées sont fictives et doivent être vérifiées avant tout usage commercial ou réglementaire\./gi,'Copie de consultation · Vérifier les signatures et pièces jointes sur le dossier opérationnel.').replace(/Document de démonstration · données fictives/gi,'Pièce rattachée au dossier transport.').replace(/DOCUMENT DE TRANSPORT · LOGIFLOW/gi,'DOCUMENT DE TRANSPORT · LOGIFLOW').replace(/données fictives/gi,'données du dossier').replace(/ajouté à la démonstration/gi,'ajouté au dossier').replace(/ — démonstration/gi,'').replace(/enregistrée dans cette démonstration/gi,'enregistrée');}
function modal(title,body,submit='Enregistrer'){let root=document.querySelector('#modalRoot');body=cleanDemoCopy(body);root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><h2>${title}</h2><button class="close" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="secondary" data-close>Annuler</button><button class="primary" data-submit>${submit}</button></div></div></div>`;root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('[data-submit]').onclick=()=>{root.innerHTML='';if(submit==='Ouvrir le suivi'){go('tracking');return}if(submit==='Attribuer la mission'){go('assignment');return}if(submit==='Choisir un fichier'){let input=document.createElement('input');input.type='file';input.accept='.pdf,.jpg,.jpeg,.png';input.onchange=()=>input.files.length&&toast(`${input.files[0].name} ajouté au dossier`);input.click();return}toast(`${title} enregistré(e)`);};}
function showRiskDetail(index){let s=shipments[index+1],risk=riskDetails[s?.[0]];if(!s||!risk)return;selectedShip=index+1;modal(`${risk.label} · ${s[0]}`,`<span class="badge ${risk.tone}">${esc(risk.label)}</span><h3>${esc(s[1])}</h3><div class="detail-row"><span>Client</span><b>${esc(s[2])}</b></div><div class="detail-row"><span>Partenaire affecté</span><b>${esc(s[3])}</b></div><div class="detail-row"><span>Livraison prévue</span><b>${esc(s[4])}</b></div><div class="detail-row"><span>Signalé par</span><b>${esc(risk.reportedBy)}</b></div><div class="detail-row"><span>Date du signalement</span><b>${esc(risk.reportedAt)}</b></div><div class="detail-row"><span>Document concerné</span><b>${esc(risk.document)}</b></div><p>${esc(risk.description)}</p><div class="assignment-note"><b>Action recommandée</b><p>${esc(risk.action)}</p><b>Impact opérationnel</b><p>${esc(risk.impact)}</p></div>`,'Ouvrir le suivi')}
function openRow(kind,i){if(kind==='tracking'){selectedShip=i;render();return}if(kind==='risk'){showRiskDetail(i);return}if(kind==='offers'){let o=offers[i];if(!o)return;selectedOfferCode=o[0];selectedBidIndex=0;modal(`Appel d’offres · ${o[0]}`,`<span class="badge">${esc(o[6])}</span><h2>${esc(o[2])}</h2><p>${esc(o[1])} · ${esc(o[3])}</p><div class="detail-row"><span>Départ prévu</span><b>${esc(o[5])}</b></div><div class="detail-row"><span>Tarif cible HT</span><b>${esc(o[4])}</b></div><div class="detail-row"><span>Chargement</span><b>22 t · 68 m³ · pièces industrielles</b></div><div class="detail-row"><span>Propositions reçues</span><b>${bidsForOffer(o).length} partenaires · comparaison des prix et délais disponible</b></div><div class="detail-row"><span>Clôture</span><b>10 nov. 2026 · 17:00</b></div>`,'Attribuer la mission');return}if(kind==='docs'){let filtered=activeDocType==='Tous'?docs:docs.filter(d=>d[4]===activeDocType),d=filtered[i];if(!d)return;modal(`Document · ${d[0]}`,documentPreview(d),'Fermer');return}if(kind==='billing'){let data=activeTab.startsWith('Devis')?quotes:activeTab==='Paiements'?payments:activeTab==='Avoirs'?credits:invoices;let b=data[i];if(!b)return;modal(`Pièce · ${b[0]}`,`<div class="bill-sheet"><div class="invoice-heading"><span>${esc(activeTab.replace(/ ·.*/,''))}</span><b>${esc(b[0])}</b></div><div class="detail-row"><span>Client / entreprise</span><b>${esc(b[1])}</b></div><div class="detail-row"><span>Date / échéance</span><b>${esc(b[2])}</b></div><div class="detail-row"><span>Montant</span><b>${esc(b[3])}</b></div><div class="detail-row"><span>Statut</span><b>${esc(b[4])}</b></div><div class="detail-row"><span>Référence de prestation</span><b>EXP-2026-0842 · novembre 2026</b></div></div>`,'Fermer');return}let row=({shipments,clients,disputes})[kind]?.[i];if(!row)return;selected=i;modal(`Détails · ${row[0]}`,`<h3>${esc(row[0])}</h3><p>Informations détaillées de l’expédition.</p><div class="detail-row"><span>Client</span><b>${esc(row[2]||row[1]||'Atlas Industries')}</b></div><div class="detail-row"><span>Trajet</span><b>${esc(row[1]||'Casablanca → Rabat')}</b></div><div class="detail-row"><span>Partenaire affecté</span><b>${esc(row[3]||'Trans Atlas')}</b></div><div class="detail-row"><span>Dernière mise à jour GPS</span><b>09 nov. 2026 · 14:28</b></div>`,'Ouvrir le suivi');}
function createFor(action){let labels=action.toLowerCase().includes('expédition')?['Client','Adresse de chargement','Adresse de livraison','Marchandises','Poids (t)','Date de départ']:action.toLowerCase().includes('offre')?['Chargeur','Trajet','Marchandises','Tarif cible (MAD)','Date de clôture']:action.toLowerCase().includes('client')||action.toLowerCase().includes('chargeur')?['Entreprise','ICE','Contact principal','Téléphone','E-mail']:action.toLowerCase().includes('transporteur')?['Entreprise','ICE','Contact','Téléphone','E-mail','Flotte']:action.toLowerCase().includes('facture')?['Client','Description','Montant HT (MAD)','Date d’échéance']:action.toLowerCase().includes('litige')?['Expédition concernée','Type d’incident','Priorité','Description']:['Titre','Référence liée','Commentaire'];modal(action,action.includes('Importer')?'<p>Sélectionnez un document PDF ou une image pour l’ajouter à la bibliothèque de documents.</p>':'<div class="form-grid">'+labels.map(n=>`<div class="field"><label>${n}</label><input placeholder="${n}"></div>`).join('')+'</div>',action.includes('Importer')?'Choisir un fichier':'Enregistrer');}
function showDisputeDetail(index){let row=disputes[index],info=disputeDetails[index];if(!row||!info)return;let label=row[2]==='Retard'?'Retard de livraison · +2 h estimées':row[2]==='Avarie'?'Marchandise endommagée à la réception':row[2]==='Facturation'?'Écart de facturation · 1 200 MAD':row[2]==='Perte'?'Colis manquant au déchargement':'Incident transport';modal(`${row[0]} · ${label}`,`<div class="detail-row"><span>Expédition / facture</span><b>${esc(row[1])}</b></div><div class="detail-row"><span>Signalé par</span><b>${esc(info.by)}</b></div><div class="detail-row"><span>Date</span><b>${esc(info.at)}</b></div><h3>Événement signalé</h3><p>${esc(info.event)}</p><div class="detail-row"><span>Priorité et statut</span><b>${esc(row[3])} · ${esc(row[4])}</b></div><div class="detail-row"><span>Preuves</span><b>${esc(info.evidence)}</b></div><div class="assignment-note"><b>Prochaine action</b><p>${esc(info.action)}</p><b>Dernière réponse</b><p>${esc(info.response)}</p></div>`,'Fermer')}
document.querySelector('#app').addEventListener('click',e=>{let reset=e.target.closest('[data-action="resetSamples"]');if(reset){e.stopImmediatePropagation();assignedOffers={};localStorage.removeItem('logiflow-assignments');shipments.length=baseShipmentCount;offers.forEach(o=>{if(o[6]==='Attribué')o[6]='Ouvert'});selected=0;selectedShip=1;selectedDispute=0;selectedRisk=0;selectedOfferCode='AO-2026-128';selectedBidIndex=0;activeTab='';page='dashboard';render();toast('Scénarios réinitialisés · vous pouvez rejouer les attributions');return}},true);
document.querySelector('#app').addEventListener('click',e=>{let action=e.target.closest('[data-action]');if(action?.dataset.action==='Confirmer l’attribution'){e.stopImmediatePropagation();confirmAssignment();return}let tab=e.target.closest('[data-tab]');if(tab&&page==='disputes'){e.stopImmediatePropagation();activeTab=tab.dataset.tab;selectedDispute=0;render();return}let row=e.target.closest('[data-row]');if(!row)return;let kind=row.dataset.row,idx=+row.dataset.index;if(kind==='bid'){e.stopImmediatePropagation();selectedBidIndex=idx;render();return}if(kind==='risk'){e.stopImmediatePropagation();selectedRisk=idx;document.querySelectorAll('tbody tr').forEach((tr,j)=>tr.classList.toggle('selected',j===idx));if(e.detail>=2)showRiskDetail(idx);return}if(kind==='disputes'){e.stopImmediatePropagation();selectedDispute=idx;if(e.detail>=2)showDisputeDetail(idx);else render();return}if(kind==='offers'&&!row.matches('tr')){e.stopImmediatePropagation();selectedOfferCode=offers[idx]?.[0]||selectedOfferCode;if(e.detail>=2)openRow('offers',idx);else{document.querySelectorAll('.offer-card').forEach(c=>c.classList.remove('offer-selected'));row.classList.add('offer-selected')}return}},true);
document.querySelector('#nav').innerHTML=navItems.map(([p,n])=>`<button data-page="${p}"><span class="nav-icon">${icon[p]}</span>${n}${p==='disputes'?'<span style="float:right" class="badge">3</span>':''}</button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#workspace').onclick=()=>toast('Espace commissionnaire · Atlas Logistics');document.querySelector('#notifications').onclick=()=>modal('Notifications','<div class="activity"><i class="dot"></i><div><b>Livraison confirmée</b><small>EXP-2026-0842 · Il y a 5 min</small></div></div><div class="activity"><i class="dot" style="background:var(--red)"></i><div><b>Retard signalé</b><small>EXP-2026-0839 · Il y a 32 min</small></div></div>','Tout marquer comme lu');document.querySelector('#userMenu').onclick=()=>modal('Votre profil','<div class="detail-row"><span>Nom</span><b>Amine Benali</b></div><div class="detail-row"><span>Rôle</span><b>Administrateur</b></div><div class="detail-row"><span>Entreprise</span><b>Atlas Logistics</b></div>','Modifier le profil');document.querySelector('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){query=e.target.value;go('tracking');document.querySelector('.local-search')?.focus();toast('Résultats de recherche dans les expéditions')}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('#globalSearch').focus()}if(e.key==='Escape')document.querySelector('#modalRoot').innerHTML=''});
document.querySelector('#app').addEventListener('click',e=>{let pg=e.target.closest('[data-page]');if(pg){go(pg.dataset.page);return}let tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;selectedBill=0;render();return}let act=e.target.closest('[data-action]');if(act){let a=act.dataset.action;if(['Nouvelle expédition','Nouvel appel d’offres','Importer un document','Nouveau client','Créer une facture','Déclarer un litige','Créer un dossier','Enregistrer un paiement'].includes(a)){createFor(a)}else if(a.includes('Télécharger')||a.includes('PDF')){toast('Document prêt à être téléchargé')}else if(a.includes('Contact')){let s=shipments[selectedShip];modal(a,`<p>${esc(s[3])} · Service exploitation</p><div class="detail-row"><span>Téléphone</span><b>+212 661 24 80 12</b></div><div class="field"><label>Votre message</label><textarea placeholder="Bonjour, pouvez-vous confirmer votre heure d’arrivée ?"></textarea></div>`,'Envoyer le message')}else if(a==='details')modal('Dossier client','<p>Fiche détaillée de la relation commerciale.</p>');else if(a==='Modifier le statut')modal('Modifier le statut','<div class="field"><label>Nouveau statut</label><select><option>En attente</option><option>En cours</option><option>Résolu</option></select></div>','Mettre à jour');else if(a==='Envoyer'||a.includes('Envoyer'))toast('Envoyé — votre action est enregistrée');else if(a==='alerts')toast('3 alertes ouvertes · 16 expéditions en retard');else if(a==='zoom')toast('Carte agrandie');else if(a==='documents'){activeDocType='Tous';go('documents')}else if(a==='faq')modal('Guide LOGIFLOW','<p>Utilisez les onglets et les filtres pour retrouver une pièce. Un clic affiche son aperçu ; un double-clic ouvre ses détails.</p>','Compris');else toast(`${a} — `);return}let folder=e.target.closest('[data-folder]');if(folder){activeDocType=folder.dataset.folder;selectedDocument=Math.max(0,docs.findIndex(d=>d[4]===activeDocType));query='';render();return}let offer=e.target.closest('[data-offer-open]');if(offer){openRow('offers',+offer.dataset.offerOpen);return}let row=e.target.closest('[data-row]');if(row){let kind=row.dataset.row,idx=+row.dataset.index;if(kind==='tracking'){selectedShip=idx;render();return}if(kind==='docs'){let filtered=activeDocType==='Tous'?docs:docs.filter(d=>d[4]===activeDocType);selectedDocument=docs.indexOf(filtered[idx]);if(e.detail>=2)openRow(kind,idx);else render();return}if(kind==='billing'){selectedBill=idx;if(e.detail>=2)openRow(kind,idx);else render();return}if(kind==='offers'&&!row.matches('tr')){if(e.detail>=2)openRow(kind,idx);else{document.querySelectorAll('.offer-card').forEach(c=>c.classList.remove('offer-selected'));row.classList.add('offer-selected')}return}selected=idx;if(e.detail>=2)openRow(kind,idx);else{document.querySelectorAll('tbody tr').forEach(r=>r.classList.remove('selected'));row.classList.add('selected');return}return}let pag=e.target.closest('.pagination button');if(pag){document.querySelectorAll('.pagination button').forEach(b=>b.classList.remove('active'));pag.classList.add('active');toast(`Page ${pag.textContent.trim()} affichée`);return}});
document.querySelector('#app').addEventListener('input',e=>{if(!e.target.matches('.local-search'))return;query=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(tr=>tr.style.display=tr.innerText.toLowerCase().includes(query)?'':'none');document.querySelectorAll('.offer-card').forEach(card=>card.style.display=card.innerText.toLowerCase().includes(query)?'':'none')});
document.querySelector('#app').addEventListener('change',e=>{if(e.target.id==='activityPeriod'){activeDashboardPeriod=e.target.value;render();return}if(!e.target.matches('select.search-field'))return;let value=e.target.options[e.target.selectedIndex]?.text||'';let cards=[...document.querySelectorAll('.offer-card')];if(/tarif le plus bas/i.test(value)){cards.sort((a,b)=>Number(a.querySelector('.offer-price strong').innerText.replace(/\D/g,''))-Number(b.querySelector('.offer-price strong').innerText.replace(/\D/g,''))).forEach(c=>c.parentElement.append(c));toast('Offres triées par tarif croissant');return}let reset=!value||/tous|toutes|trier|ETD/i.test(value);document.querySelectorAll('tbody tr').forEach(tr=>tr.style.display=reset||tr.innerText.toLowerCase().includes(value.toLowerCase())?'':'none');cards.forEach(card=>card.style.display=reset||card.innerText.toLowerCase().includes(value.toLowerCase())?'':'none');if(!reset)toast(`Filtre appliqué : ${value}`)});
render();
